 * (`kind:`/`in:`/`project:`) is only parsed out for workspaces with
 * `advanced_search`; otherwise the query is matched as literal free text, a
 * colon included (ADR 0007 rules 1, 3 and 4). This is the same parser the
 * dialog uses for its hint line, so what it says it understood is what gets
 * searched.
 */
export async function search(
  actor: Actor,
  input: SearchQueryInput,
): Promise<Page<SearchHit>> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "issue:read", orgResource(input.orgId));

  const verdict = await consumeRateLimit(input.orgId, SEARCH_QUERY_BUCKET);
  if (!verdict.allowed) {
    throw new Error(
      `Search rate limit reached; try again after ${verdict.resetAt}`,
    );
  }

  const org = await orgRepo.findOrgById(input.orgId);
  const advanced = isEnabled("advanced_search", {
    orgId: input.orgId,
    userId: actor.userId,
    plan: org?.plan ?? "free",
    role: actor.role,
    overrides: org?.settings.enabledFlagOverrides,
  });

  let rawText = input.q;
  let kinds = input.kinds;
  let projectId = input.projectId;

  if (advanced) {
    const tokens = extractSearchQueryTokens(input.q);
    rawText = tokens.text;
    if (tokens.kinds.length > 0) kinds = tokens.kinds;
    if (tokens.projectId !== null) projectId = tokens.projectId;
  } else {
    kinds = ["issue"];
  }

  const text = normaliseQuery(rawText);
  const page = await searchRepo.searchDocuments({
    ...input,
    q: text,
    kinds,
    projectId,
